/// <summary>
/// Finds a record
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <param name = "_update">_update</param>
/// <returns>Record</returns>
static public NDXMultipleS_SalesQuotationRange find(InventTable _inventTable, boolean _update = false)
{
    NDXMultipleS_SalesQuotationRange lNDXMultipleS_SalesQuotationRange;

    if(_inventTable)
    {
        lNDXMultipleS_SalesQuotationRange.selectForUpdate(_update);

        select lNDXMultipleS_SalesQuotationRange
            where lNDXMultipleS_SalesQuotationRange.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXMultipleS_SalesQuotationRange;
}

/// <summary>
/// Returns all validation quotation ids ranges for an item as string
/// </summary>
/// <param name = "_itemRecId">_itemRecId</param>
/// <returns>String of sale quotation ids ranges</returns>
static str Range2String(RecId _itemRecId)
{
    #define.Comma(' ,')

    NDXMultipleS_SalesQuotationRange       nDX_MultipleS_QuotationRange;
    str range2String;
    boolean             lFirst = true;
    ;
    while select nDX_MultipleS_QuotationRange
        where nDX_MultipleS_QuotationRange.RefRecId_InventTable == _itemRecId
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += nDX_MultipleS_QuotationRange.RangeQuotation;
    }
    return range2String;
}

/// <summary>
/// Writes a long for record change
/// </summary>
/// <param name = "_orig">record before</param>
/// <param name = "_current">record after</param>
private void writeLog(NDXMultipleS_SalesQuotationRange _orig, NDXMultipleS_SalesQuotationRange _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.RangeQuotation != _current.RangeQuotation)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::QuotationRange;

        multipleS_Log.RangeValue        =  _current.RangeQuotation;

        if (!_orig.RangeQuotation)              // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.RangeQuotation)      // Löschung
        {
            multipleS_Log.RangeValue        = _orig.RangeQuotation;
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                    // Änderung
        {
            multipleS_Log.RangeValue        += strFmt("@ApplicationFoundation:DocuDeletedRefCaptionGeneratorFromLabel", _orig.RangeQuotation);
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}

public void insert()
{
    NDXMultipleS_SalesQuotationRange orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXMultipleS_SalesQuotationRange orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void delete()
{
    NDXMultipleS_SalesQuotationRange orig = this.orig();
    super();
    this.writeLog(orig, null);
}
